def fizzbuzz(n):
    resultado = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            resultado.append('FizzBuzz')
        elif i % 3 == 0:
            resultado.append('Fizz')
        elif i % 5 == 0:
            resultado.append('Buzz')
        else:
            resultado.append(str(i))
    return resultado

def parsear_duracion(s):
    s = s.strip()
    total_minutos = 0

    # Separar componentes: horas y minutos
    parts = s.replace('h', ' ').replace('m', ' ').split()

    for part in parts:
        if part.startswith('h'):
            # Extraer valor numérico después de 'h'
            valor = float(part[1:])
            total_minutos += valor * 60
        elif part.startswith('m'):
            # Extraer valor numérico después de 'm'
            valor = float(part[1:])
            total_minutos += valor

    return int(total_minutos)

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    l = 0
    r = len(lista) - 1
    while l <= r:
        m = (l + r) // 2
        if lista[m] == x:
            return m
        elif lista[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    numeros = [(9, "IX"), (4, "IV"), (1, "I"),
                (90, "XC"), (40, "XL"), (900, "CM"),
                (500, "D"), (900, "CM"), (100, "C"),
                (50, "L"), (90, "XC"), (10, "X"),
                (5, "V"), (9, "IX"), (1, "I")]
    res = ""
    while n > 0:
        for valor, simbolo in numeros:
            if n >= valor:
                res += simbolo
                n -= valor
    return res

def desde_romano(s):
    numeros = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    i = 0
    while i < len(s):
        valor = numeros.get(s[i], 0)
        if i + 1 < len(s) and numeros.get(s[i+1], 0) > valor:
            resultado += numeros.get(s[i+1], 0) - valor
            i += 2
        else:
            resultado += valor
            i += 1
    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = None
    max_longitud = -1

    i = 0
    while i < len(lista):
        elemento = lista[i]
        j = i
        while j < len(lista) and lista[j] == elemento:
            j += 1
        longitud = j - i

        if longitud > max_longitud:
            max_longitud = longitud
            max_elemento = elemento

        i = j

    return (max_elemento, max_longitud)

def a_camel(s):
    words = s.split('_')
    return words[0] + ''.join(word[0].upper() + word[1:] for word in words[1:])

def a_snake(s):
    result = []
    prev_upper = False
    for char in s:
        if char.isupper():
            if prev_upper and char != s[0]:
                result.append('_')
            result.append(char.lower())
            prev_upper = True
        else:
            result.append(char)
            prev_upper = False
    return ''.join(result)

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for i in range(2, n + 1):
        if all(i % p != 0 for p in range(2, int(i**0.5) + 1)):
            primos_list.append(i)
    return primos_list

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar por inicio, y en caso de ties, por fin
    intervalos = sorted(intervalos, key=lambda x: (x[0], x[1]))

    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        ultimo_fin = fusionados[-1][1]
        if inicio <= ultimo_fin:
            # Fusionar: tocar en un extremo se cubre con <=
            fusionados[-1] = (fusionados[-1][0], max(ultimo_fin, fin))
        else:
            fusionados.append((inicio, fin))

    return fusionados

def es_anagrama(a, b):
    def normalizar(texto):
        return sorted(letra for letra in texto.lower() if letra.isalpha())
    return normalizar(a) == normalizar(b)

def comprimir(s):
    if not s:
        return s

    compresion = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compresion.append(s[i - 1])
            compresion.append(str(count))
            count = 1
    compresion.append(s[-1])
    compresion.append(str(count))
    comprimido = ''.join(compresion)

    return comprimido if len(comprimido) < len(s) else s

def balanceado(texto):
    if not texto:
        return True

    colores = {'(': ')', '{': '}', '}': '}', '[': ']'}
    stack = []

    for char in texto:
        if char in colores:
            stack.append(char)
        elif char in ')' or char in '}' or char in ']':
            if not stack:
                return False
            ultimo = stack.pop()
            if colores[ultimo] != char:
                return False

    return len(stack) == 0

def transpuesta(matriz):
    if not matriz:
        return []
    n = len(matriz)
    resultados = []
    for i in range(len(matriz[0])):
        fila = []
        for j in range(n):
            fila.append(matriz[j][i])
        resultados.append(fila)
    return resultados

def raiz_digital(n):
    while n >= 10:
        suma = 0
        while n > 0:
            suma += n % 10
            n //= 10
        n = suma
    return n

def sin_duplicados(lista):
    resultado = []
    for elemento in lista:
        if elemento not in resultado:
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    distinct_values = sorted(set(lista), reverse=True)
    if len(distinct_values) < n:
        return None
    return distinct_values[n - 1]

def formatear_bytes(n):
    if n == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB']
    for i in range(len(units)):
        unit = units[i]
        value = n / (1024 ** i)
        if value < 1024:
            if i == 0:
                return f'{int(value)} B'
            return f'{value:.1f} {unit}'
    return f'{n} B'

def _lotes(lista, tamano):
    if not lista:
        return []
    resultados = []
    inicio = 0
    while lista:
        lote = lista[inicio:inicio + tamano]
        resultados.append(lote)
        inicio += tamano
    return resultados
